/**
 * 文件工作台持久化存储 —— 后端 JSON 配置文件（按类型分文件）。
 *
 * 不同持久化类型各自写入独立 JSON 文件，目录为：
 *   {DSH_HOME | ~/.dsh}/fileworkbench/
 *   ├── prefs.json     界面偏好
 *   ├── favorites.json 收藏路径
 *   ├── recent.json    最近打开记录
 *   ├── layout.json    面板列宽布局
 *   └── scrolls.json   打开文件的滚动位置缓存
 *
 * key → 文件名 由白名单 ALLOWED 约束，杜绝路径穿越。
 */
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { join } from "node:path";
import { homedir } from "node:os";

/** 允许持久化的 key 白名单（key 即产物文件名的一部分）。
 *  界面风格（classic / macos）隔离所需的键会在基础键后追加后缀（如 dockLayout.macos），
 *  这类带后缀的键同样允许读写，并各自写入独立 JSON 文件，从而两套风格数据互不覆盖。 */
export const PERSIST_KEYS = ["prefs", "favorites", "recent", "layout", "scrolls", "tabs", "aiWin", "termWin", "dockLayout", "dockLayoutConfig", "dockFloatState", "drafts", "layoutSnapshots", "taskLogs"] as const;
export type PersistKey = (typeof PERSIST_KEYS)[number];

/** 界面风格隔离后缀（macos 风格布局状态键使用）。 */
const STYLE_SUFFIX = ".macos";

/** 持久化文件存放目录：{DSH_HOME | ~/.dsh}/fileworkbench/。 */
function stateDir(): string {
  const dshHome = process.env.DSH_HOME || join(homedir(), ".dsh");
  return join(dshHome, "fileworkbench");
}

/** 去掉风格后缀得到基础白名单键（原样返回时按白名单校验）。 */
function baseKey(key: string): string {
  return key.endsWith(STYLE_SUFFIX) ? key.slice(0, -STYLE_SUFFIX.length) : key;
}

/** key 是否合法：命中基础白名单，或为「基础白名单 + 风格后缀」的隔离键。 */
function isPersistKey(key: string): boolean {
  return (PERSIST_KEYS as readonly string[]).includes(baseKey(key));
}

function fileFor(key: string): string {
  return join(stateDir(), `${key}.json`);
}

/** 列出应参与“全量读取”的键：基础键 + 对应的风格隔离后缀键。 */
function effectiveKeys(): string[] {
  const out: string[] = [];
  for (const k of PERSIST_KEYS) {
    out.push(k);
    out.push(k + STYLE_SUFFIX);
  }
  return out;
}

/** 读取某个持久化 key 的配置（文件不存在或损坏时返回 undefined）。 */
export async function getPersistKey(key: string): Promise<unknown> {
  if (!isPersistKey(key)) return undefined;
  try {
    return JSON.parse(await readFile(fileFor(key), "utf8"));
  } catch {
    return undefined;
  }
}

/** 写入某个持久化 key 到其独立配置文件。 */
export async function setPersistKey(key: string, value: unknown): Promise<void> {
  if (!isPersistKey(key)) {
    throw new Error(`unknown persist key: ${key}`);
  }
  await mkdir(stateDir(), { recursive: true });
  await writeFile(fileFor(key), JSON.stringify(value ?? null), "utf8");
}

/** 汇总所有持久化 key 为单个对象（供客户端一次性读取全量，含风格隔离后缀键）。 */
export async function getAllPersist(): Promise<Record<string, unknown>> {
  const out: Record<string, unknown> = {};
  for (const k of effectiveKeys()) {
    const v = await getPersistKey(k);
    if (v !== undefined) out[k] = v;
  }
  return out;
}